import * as fs from "fs";
import MiniCssExtractPlugin from "mini-css-extract-plugin";
import * as path from "path";
import webpack, { Configuration } from "webpack";
import { PurgeCSSPlugin } from "../src";
import { parseCssModuleExports } from "../src/css-modules";

// eslint-disable-next-line @typescript-eslint/no-require-imports
const fixture = require("./css-modules/webpack.config.js");

function runWebpack(config: Configuration): Promise<void> {
  return new Promise((resolve, reject) => {
    webpack(config, (err, stats) => {
      if (err) reject(err);
      else if (stats?.hasErrors()) reject(new Error(stats.toString()));
      else resolve();
    });
  });
}

describe("parseCssModuleExports", () => {
  it("reads the default export of mini-css-extract-plugin", () => {
    const source = `// extracted by mini-css-extract-plugin
export default {"modUsed":"modUsed__a1","modComposed":"modComposed__b2 base__c3","odd-name":"odd-name__d4"};`;
    expect(parseCssModuleExports(source)).toEqual([
      { name: "modUsed", classNames: ["modUsed__a1"] },
      { name: "modComposed", classNames: ["modComposed__b2", "base__c3"] },
      { name: "odd-name", classNames: ["odd-name__d4"] },
    ]);
  });

  it("reads a CommonJS export", () => {
    const source = `// extracted by css-extract-rspack-plugin
module.exports = {"modUsed":"modUsed__a1"};`;
    expect(parseCssModuleExports(source)).toEqual([
      { name: "modUsed", classNames: ["modUsed__a1"] },
    ]);
  });

  it("reads named exports", () => {
    const source = `// extracted by mini-css-extract-plugin
var _1 = "namedUsed__a1";
var _2 = "named-odd__b2 namedUsed__a1";
export { _1 as "namedUsed", _2 as "named-odd" }
export default { "namedUsed": _1, "named-odd": _2 }
export const direct = "direct__c3";`;
    expect(parseCssModuleExports(source)).toEqual(
      expect.arrayContaining([
        { name: "namedUsed", classNames: ["namedUsed__a1"] },
        { name: "named-odd", classNames: ["named-odd__b2", "namedUsed__a1"] },
        { name: "direct", classNames: ["direct__c3"] },
      ]),
    );
  });

  it("reads the export map generated by Rspack", () => {
    const source = `var exports = {
  "modUsed": "src_card_module_css-modUsed",
  "modComposed": "src_card_module_css-modComposed" + " " + "src_card_module_css-base",
};

module.exports = exports;`;
    expect(parseCssModuleExports(source)).toEqual([
      { name: "modUsed", classNames: ["src_card_module_css-modUsed"] },
      {
        name: "modComposed",
        classNames: [
          "src_card_module_css-modComposed",
          "src_card_module_css-base",
        ],
      },
    ]);
  });

  it("reads the classes composed from another module with Rspack", () => {
    const source = `var exports = {
  "btn": "src_btn_module_css-btn" + " " + __webpack_require__("./src/shared.module.css")["sharedBase"],
  "H": "BY0Sh6" + " " + __webpack_require__(378)["h"],
  "I": "lafGYW " + e(378).h,
  "plain": "plain__a1",
};`;
    expect(parseCssModuleExports(source)).toEqual([
      {
        name: "btn",
        classNames: ["src_btn_module_css-btn"],
        references: [
          { moduleId: "./src/shared.module.css", name: "sharedBase" },
        ],
      },
      {
        name: "H",
        classNames: ["BY0Sh6"],
        references: [{ moduleId: "378", name: "h" }],
      },
      {
        name: "I",
        classNames: ["lafGYW"],
        references: [{ moduleId: "378", name: "h" }],
      },
      { name: "plain", classNames: ["plain__a1"] },
    ]);
  });

  it("finds no export in the code of a global stylesheet", () => {
    expect(
      parseCssModuleExports(
        "// extracted by mini-css-extract-plugin\nexport {};",
      ),
    ).toEqual([]);
  });
});

describe("CSS modules with webpack", () => {
  const outputDirectory = path.resolve(__dirname, "js", "css-modules-webpack");
  let css: string;

  beforeAll(async () => {
    await runWebpack({
      mode: "production",
      devtool: false,
      context: fixture.context,
      entry: fixture.entry,
      output: { path: outputDirectory, clean: true },
      // keep the CSS readable, the JavaScript is minimized after the purge
      module: { rules: fixture.cssRules(MiniCssExtractPlugin.loader) },
      plugins: [
        new MiniCssExtractPlugin(),
        new PurgeCSSPlugin({ paths: fixture.contentPaths }),
      ],
    });
    css = await fs.promises.readFile(
      path.join(outputDirectory, "main.css"),
      "utf-8",
    );
  });

  it("keeps the classes of the exports used in the content", () => {
    // default import: `styles.modUsed`
    expect(css).toMatch(/\.modUsed__[\w-]{5} \{/);
    expect(css).toMatch(/\.modComposed__[\w-]{5} \{/);
    // named import: `named.namedUsed`
    expect(css).toMatch(/\.namedUsed__[\w-]{5} \{/);
  });

  it("keeps the classes composed by a used export", () => {
    expect(css).toMatch(/\.base__[\w-]{5} \{/);
  });

  it("keeps the classes composed from another file", () => {
    expect(css).toMatch(/\.modCrossFile__[\w-]{5} \{/);
    expect(css).toMatch(/\.sharedBase__[\w-]{5} \{/);
  });

  it("removes the classes of the exports not used in the content", () => {
    expect(css).not.toMatch(/modUnused__/);
    expect(css).not.toMatch(/namedUnused__/);
    expect(css).not.toMatch(/sharedUnused__/);
    // only used in a selector of the stylesheet, never exported to the content
    expect(css).not.toMatch(/inner__/);
  });

  it("purges the global css as before", () => {
    expect(css).toMatch(/\.used-global \{/);
    expect(css).not.toMatch(/unused-global/);
  });
});

describe.each(["production", "development"] as const)(
  "CSS modules with the native CSS of webpack in %s",
  (mode) => {
    const outputDirectory = path.resolve(
      __dirname,
      "js",
      `css-modules-webpack-native-${mode}`,
    );
    let css: string;

    beforeAll(async () => {
      await runWebpack({
        mode,
        devtool: false,
        context: fixture.context,
        // named exports: no default export
        entry: fixture.namespaceEntry,
        output: { path: outputDirectory, clean: true },
        experiments: { css: true },
        module: {
          rules: [{ test: /\.css$/, type: "css/auto" }],
          generator: { "css/auto": { localIdentName: "[local]__[hash]" } },
        },
        // keep the CSS readable, PurgeCSS runs before the minimizers anyway
        optimization: { minimize: false },
        plugins: [new PurgeCSSPlugin({ paths: fixture.namespaceContentPaths })],
      });
      css = await fs.promises.readFile(
        path.join(outputDirectory, "main.css"),
        "utf-8",
      );
    });

    it("keeps the classes of the exports used in the content", () => {
      expect(css).toMatch(/\.modUsed__[\w-]+ \{/);
      expect(css).toMatch(/\.modComposed__[\w-]+ \{/);
      expect(css).toMatch(/\.base__[\w-]+ \{/);
      expect(css).toMatch(/\.namedUsed__[\w-]+ \{/);
    });

    it("keeps the classes composed from another file", () => {
      expect(css).toMatch(/\.modCrossFile__[\w-]+ \{/);
      expect(css).toMatch(/\.sharedBase__[\w-]+ \{/);
    });

    it("removes the classes of the exports not used in the content", () => {
      expect(css).not.toMatch(/modUnused__/);
      expect(css).not.toMatch(/namedUnused__/);
      expect(css).not.toMatch(/sharedUnused__/);
      expect(css).not.toMatch(/inner__/);
    });

    it("purges the global css", () => {
      expect(css).toMatch(/\.used-global \{/);
      expect(css).not.toMatch(/unused-global/);
    });
  },
);

// the extractor yields `${styles.modUsed}` as a single token, not `styles`
// and `modUsed`
describe("CSS modules with an extractor that does not split on dots", () => {
  const outputDirectory = path.resolve(
    __dirname,
    "js",
    "css-modules-webpack-extractor",
  );
  let css: string;

  beforeAll(async () => {
    await runWebpack({
      mode: "development",
      devtool: false,
      context: fixture.context,
      entry: fixture.entry,
      output: { path: outputDirectory, clean: true },
      module: { rules: fixture.cssRules(MiniCssExtractPlugin.loader) },
      plugins: [
        new MiniCssExtractPlugin(),
        new PurgeCSSPlugin({
          paths: fixture.contentPaths,
          defaultExtractor: (content: string) =>
            content.match(/[^<>"'`\s]*[^<>"'`\s:]/g) ?? [],
        }),
      ],
    });
    css = await fs.promises.readFile(
      path.join(outputDirectory, "main.css"),
      "utf-8",
    );
  });

  it("keeps the classes of the exports used in the content", () => {
    expect(css).toMatch(/\.modUsed__[\w-]{5} \{/);
    expect(css).toMatch(/\.modComposed__[\w-]{5} \{/);
    expect(css).toMatch(/\.base__[\w-]{5} \{/);
    expect(css).toMatch(/\.namedUsed__[\w-]{5} \{/);
    expect(css).toMatch(/\.modCrossFile__[\w-]{5} \{/);
  });

  it("removes the classes of the exports not used in the content", () => {
    expect(css).not.toMatch(/modUnused__/);
    expect(css).not.toMatch(/namedUnused__/);
    expect(css).not.toMatch(/inner__/);
  });
});
